}

{
  "requirements": [
    {
      "required_fact": "嵌入模型名称",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确说明当前嵌入模型为 qwen3-embedding:0.6b-q8_0。","supported": true,
      "answer": "qwen3-embedding:0.6b-q8_0"
    },
    {
      "required_fact": "生成模型名称",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确说明生成模型为 qwen3.5:4b-q4_K_M。","supported": true,
      "answer": "qwen3.5:4b-q4_K_M"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "程序是否会自动读取 .env 文件",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确说明'程序不会自动读取.env文件'。","supported": true,"answer": "否，程序不会自动读取.env文件。"}
    ]
  }

{
  "requirements": [
    {
      "required_fact": "上传单个文件时允许的最大大小是多少？",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文 E1S1 明确说明：'单个文件必须非空，且大小不得超过 10 MiB。'",
      "supported": true,
      "answer": "上传单个文件时允许的最大大小是 10 MiB。"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "知识库能直接接收哪些文件格式",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确列出允许导入的格式为 .md、.txt 和文本型 .pdf 文件。","supported": true,
      "answer": "知识库可直接接收 .md、.txt 和文本型 .pdf 文件格式。"
    },
    {
      "required_fact": "可以上传 ZIP 吗",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确说明不接收 ZIP 文件。","supported": true,
      "answer": "不可以上传 ZIP 文件，系统明确不接收 ZIP 格式。"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "当前系统能否直接识别只有扫描图片、提取不出文字的 PDF",
      "source_ids": [
        "E1S1"
      ],
      "evidence_finding": "原文明确说明'当前没有 OCR 功能，不能直接处理无可提取文字的扫描 PDF'。","supported": true,"answer": "不能直接识别。"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "嵌入模型 digest 改变后，之前建立的向量索引是否还能直接沿用",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文 E1S1 明确指出：'模型 digest 改变后，旧索引不能用于新的模型标识，需要重新建立索引。'",
      "supported": true,
      "answer": "不能直接沿用；模型 digest 改变后，旧索引不能用于新的模型标识，必须重新建立索引。"
    }
  ]
}

{
  "requirements": [
